  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Dexetimide, a 1-benzylpiperidine-containing PET ligand, is described as having good brain penetration, supporting CNS access for the query's N-benzylpiperidine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A closely related N-benzylpiperidine spiro ligand showed a brain-to-blood ratio of 2.2 rising to 6.3 in mice, directly demonstrating robust BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "An N-benzylpiperidine-containing radiotracer showed ~4% ID/g brain uptake at 5 min in mice, indicating favorable brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A 1-benzylpiperidine iodobenzamide accumulated significantly in monkey brain, confirming CNS access for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A 1-benzyl-4-piperidinyl benzamide showed significant and lasting high brain uptake in mice, supporting brain penetration of N-benzylpiperidine derivatives.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "The lipophilic dimethoxybenzamide Org-25543 crossed the BBB with a free brain/plasma ratio of ~0.5, supporting CNS access for lipophilic dimethoxy-substituted ligands.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic dimethoxy-tetralone bearing a 1-benzylpiperidine moiety; multiple independent in vivo studies on closely related N-benzylpiperidine and lipophilic CNS ligands demonstrate robust brain uptake, so meaningful CNS access is predicted.",
